select * from api.app_user;
select * from api.status;
select * from api.company;
select current_user; \du
select proname from pg_proc p join pg_namespace n on n.oid=pronamespace where nspname in ('api','public');
select tgname, tgrelid::regclass from pg_trigger where not tgisinternal;

select count(*) filter (where amount is null) nulls from api.application;
select relname, relrowsecurity from pg_class where relnamespace='api'::regnamespace and relkind='r';
select grantee, table_name, privilege_type from information_schema.role_table_grants where table_schema='api' and grantee not in ('postgres') order by 1,2;
select rolname, rolbypassrls from pg_roles where rolname in ('authenticator','anon','applicant','expert','fund_admin');

begin;
create schema if not exists priv;
revoke all on schema priv from public;
grant usage on schema priv to fund_admin, expert, applicant;

create or replace function priv.login() returns text language sql stable as
$$ select nullif(current_setting('request.jwt.claims', true),'')::json->>'login' $$;
create or replace function priv.via() returns text language sql stable as
$$ select case when lower(coalesce(nullif(current_setting('request.headers', true),'')::json->>'x-client',''))='ai' then 'ai' else 'human' end $$;
create or replace function priv.cur_company() returns int language sql stable security definer set search_path=pg_catalog,api as
$$ select company_id from api.app_user where login = priv.login() $$;
create or replace function priv.ord(sid int) returns int language sql stable security definer set search_path=pg_catalog,api as
$$ select ord from api.status where id=sid $$;
grant execute on function priv.login(), priv.via(), priv.cur_company(), priv.ord(int) to fund_admin, expert, applicant;

-- constraints R6/R7
alter table api.application alter column amount set not null;
alter table api.application add constraint amount_valid check (amount <> 'NaN' and amount >= 0);
alter table api.application add constraint revenue_valid check (revenue is null or (revenue <> 'NaN' and revenue >= 0));

-- audit & confirmation
create table api.audit(id bigserial primary key, at timestamptz not null default now(), actor text, via text not null, op text not null, app_id int);
create table api.confirmation(id bigserial primary key, actor text not null default priv.login(), op text not null check (op in ('delete','bulk_update')), app_id int, created_at timestamptz not null default now(), used boolean not null default false);

-- triggers
create or replace function priv.t_confirm_guard() returns trigger language plpgsql as $$
begin
  if priv.via()='ai' then raise exception 'confirmation must be created by a human request' using errcode='42501'; end if;
  new.actor := priv.login(); new.used := false; new.created_at := now();
  return new;
end $$;
create trigger confirm_guard before insert on api.confirmation for each row execute function priv.t_confirm_guard();

create or replace function priv.t_app_ins() returns trigger language plpgsql security definer set search_path=pg_catalog,api as $$
begin
  if new.status_id is distinct from 20000 then raise exception 'new application must be in status Черновик' using errcode='23514'; end if;
  return new;
end $$;
create trigger a_ins before insert on api.application for each row execute function priv.t_app_ins();

create or replace function priv.t_app_upd() returns trigger language plpgsql security definer set search_path=pg_catalog,api as $$
declare o int; n int; lim numeric;
begin
  o:=priv.ord(old.status_id); n:=priv.ord(new.status_id);
  if n is null then raise exception 'unknown status' using errcode='23514'; end if;
  if n<>o and not ((o<3 and n=o+1) or (o=3 and n in (4,5))) then
    raise exception 'status transition not allowed' using errcode='23514'; end if;
  if n in (4,5) and coalesce(btrim(new.verdict),'')='' then
    raise exception 'verdict required to approve/reject' using errcode='23514'; end if;
  if n=4 then
    select funding_limit into lim from api.company where id=new.company_id;
    if lim is null or new.amount > lim then raise exception 'amount exceeds company limit' using errcode='23514'; end if;
  end if;
  return new;
end $$;
create trigger b_upd before update on api.application for each row execute function priv.t_app_upd();

create or replace function priv.t_app_del() returns trigger language plpgsql security definer set search_path=pg_catalog,api as $$
declare cid bigint;
begin
  if priv.via()='ai' then
    select id into cid from api.confirmation where actor=priv.login() and op='delete' and app_id=old.id and not used and created_at>now()-interval '10 minutes' order by id limit 1 for update;
    if cid is null then raise exception 'delete by agent requires human confirmation' using errcode='42501'; end if;
    update api.confirmation set used=true where id=cid;
  end if;
  return old;
end $$;
create trigger c_del before delete on api.application for each row execute function priv.t_app_del();

create or replace function priv.t_app_bulk() returns trigger language plpgsql security definer set search_path=pg_catalog,api as $$
declare cnt int; cid bigint;
begin
  select count(*) into cnt from nt;
  if cnt>1 and priv.via()='ai' then
    select id into cid from api.confirmation where actor=priv.login() and op='bulk_update' and not used and created_at>now()-interval '10 minutes' order by id limit 1 for update;
    if cid is null then raise exception 'bulk update by agent requires human confirmation' using errcode='42501'; end if;
    update api.confirmation set used=true where id=cid;
  end if;
  return null;
end $$;
create trigger d_bulk after update on api.application referencing new table as nt for each statement execute function priv.t_app_bulk();

create or replace function priv.t_audit() returns trigger language plpgsql security definer set search_path=pg_catalog,api as $$
begin
  insert into api.audit(actor,via,op,app_id) values (priv.login(), priv.via(), tg_op, case when tg_op='DELETE' then old.id else new.id end);
  return null;
end $$;
create trigger z_audit after insert or update or delete on api.application for each row execute function priv.t_audit();

-- privileges
revoke all on api.application, api.company, api.status, api.audit, api.confirmation from public, anon, applicant, expert;
revoke truncate on api.application, api.company, api.status from fund_admin;
grant all on api.audit, api.confirmation to fund_admin; revoke truncate on api.audit, api.confirmation from fund_admin;
grant usage on all sequences in schema api to fund_admin, expert, applicant;
grant select on api.status to fund_admin, expert, applicant;
grant select on api.company to expert, applicant;
grant select(id,number,company_id,status_id,amount,revenue,description,verdict) on api.application to applicant;
grant insert(number,company_id,status_id,amount,revenue,description) on api.application to applicant;
grant update(number,status_id,amount,revenue,description) on api.application to applicant;
grant delete on api.application to applicant;
grant select on api.application to expert;
grant update(status_id,verdict,expert) on api.application to expert;
grant select, insert on api.confirmation to expert, applicant;
revoke update, delete on api.audit from fund_admin;
revoke insert on api.audit from fund_admin;

-- RLS
alter table api.application enable row level security;
alter table api.company enable row level security;
alter table api.confirmation enable row level security;
alter table api.application force row level security;
create policy adm on api.application to fund_admin using (true) with check (true);
create policy ap_sel on api.application for select to applicant using (company_id=priv.cur_company());
create policy ap_ins on api.application for insert to applicant with check (company_id=priv.cur_company() and priv.ord(status_id)=1);
create policy ap_upd on api.application for update to applicant using (company_id=priv.cur_company() and priv.ord(status_id)<3) with check (company_id=priv.cur_company() and priv.ord(status_id)<3);
create policy ap_del on api.application for delete to applicant using (company_id=priv.cur_company() and priv.ord(status_id)=1);
create policy ex_sel on api.application for select to expert using (priv.ord(status_id)>=2);
create policy ex_upd on api.application for update to expert using (priv.ord(status_id) in (2,3)) with check (priv.ord(status_id) in (3,4,5));
create policy co_adm on api.company to fund_admin using (true) with check (true);
create policy co_ex on api.company for select to expert using (true);
create policy co_ap on api.company for select to applicant using (id=priv.cur_company());
create policy cf_all on api.confirmation to fund_admin, expert, applicant using (actor=priv.login()) with check (actor=priv.login());
commit;
notify pgrst, 'reload schema';

